// Campus map data (generated by scripts/build-campus-data.mjs from OpenStreetMap) and the small
// amount of 2D geometry the world builder needs. Coordinates: +x east, +z south, metres.

import raw from './campusData.json';
import { BUILDING_OVERRIDES } from './buildingOverrides.ts';

export type Pt = [number, number];

export interface BuildingData {
  name?: string;
  pts: Pt[];
  levels?: number;
  height?: number;
  wall?: string;
  roof?: string;
  roofShape?: string;
  kind: string;
  inside: boolean;
  /** 'ms': footprint from Microsoft's building footprints (missing from OSM). */
  source?: 'ms';
  /** Has a walkable interior (buildingOverrides.ts). */
  enterable?: boolean;
}

export interface AreaData {
  kind: 'pitch' | 'ground' | 'park' | 'grass' | 'orchard' | 'scrub' | 'parking' | 'water' | 'plaza' | 'residential';
  pts: Pt[];
  sport?: string;
  name?: string;
  surface?: string;
}

export interface LineData {
  kind: string;
  pts: Pt[];
  w: number;
  surface?: string;
  name?: string;
  area?: boolean;
  /** Passes under a building (OSM tunnel=building_passage / covered): a walk-through passage. */
  tunnel?: boolean;
}

export interface PointData {
  kind: 'tree' | 'bench' | 'lamp' | 'statue' | 'fountain' | 'flagpole' | 'board' | 'bin' | 'watertower' | 'tap' | 'poi';
  x: number;
  z: number;
  name?: string;
}

export interface CampusData {
  source: string;
  origin: { lat: number; lon: number };
  boundary: Pt[];
  buildings: BuildingData[];
  areas: AreaData[];
  lines: LineData[];
  points: PointData[];
  elevation: { half: number; n: number; base: number; h: number[] };
}

export const DATA = raw as unknown as CampusData;
DATA.buildings = clearRoads(dedupeBuildings(DATA.buildings));
for (const b of DATA.buildings) {
  const o = b.name ? BUILDING_OVERRIDES[b.name] : undefined;
  if (!o) continue;
  if (o.levels !== undefined) b.levels = o.levels;
  if (o.height !== undefined || o.levels !== undefined) b.height = o.height;
  if (o.enterable) b.enterable = true;
}

/**
 * Buildings must not stand on roads or paths. A small OSM building drawn over a
 * road (a guard booth by the gate, say) is nudged off it, up to 6 m; Microsoft
 * footprints that land on a road or path are imprecise and dropped. Passages
 * (tunnel) run through buildings on purpose and are ignored here.
 */
function clearRoads(list: BuildingData[]): BuildingData[] {
  const ROADS = new Set(['primary', 'secondary', 'tertiary', 'residential', 'unclassified', 'service', 'track', 'living_street']);
  const PATHS = new Set(['footway', 'path', 'pedestrian', 'steps', 'cycleway']);
  const out: BuildingData[] = [];
  for (const b of list) {
    let pts = b.pts;
    let keep = true;
    for (let pass = 0; pass < 3 && keep; pass += 1) {
      let fix: { nx: number; nz: number; d: number } | null = null;
      for (const l of DATA.lines) {
        if (l.tunnel || l.area || !(ROADS.has(l.kind) || PATHS.has(l.kind))) continue;
        for (let i = 0; i < l.pts.length - 1 && !fix; i += 1) {
          const a = l.pts[i];
          const c = l.pts[i + 1];
          const len = Math.hypot(c[0] - a[0], c[1] - a[1]);
          if (len < 0.01) continue;
          // Does this segment run through the footprint?
          let through = false;
          for (let t = 0.05; t < 1 && !through; t += 0.1) through = pointInPoly(a[0] + (c[0] - a[0]) * t, a[1] + (c[1] - a[1]) * t, pts);
          if (!through) continue;
          if (b.source === 'ms') {
            keep = false;
            break;
          }
          if (!ROADS.has(l.kind) || Math.abs(polyArea(pts)) > 120) continue;
          // Push the footprint to the side its centre is on, clear of the road edge.
          const nx = -(c[1] - a[1]) / len;
          const nz = (c[0] - a[0]) / len;
          const [cx, cz] = centroid(pts);
          const side = (cx - a[0]) * nx + (cz - a[1]) * nz >= 0 ? 1 : -1;
          const minD = Math.min(...pts.map(([x, z]) => ((x - a[0]) * nx + (z - a[1]) * nz) * side));
          fix = { nx: nx * side, nz: nz * side, d: l.w / 2 + 0.6 - minD };
        }
        if (!keep || fix) break;
      }
      if (!keep || !fix) break;
      if (fix.d > 6) {
        keep = false;
        break;
      }
      pts = pts.map(([x, z]) => [x + fix!.nx * fix!.d, z + fix!.nz * fix!.d] as Pt);
    }
    if (keep) out.push(pts === b.pts ? b : { ...b, pts });
  }
  return out;
}

/**
 * OpenStreetMap sometimes has a building twice (an unnamed outline under the named
 * one). Two sets of walls in the same place flicker (z-fighting), so a building
 * mostly covered by another is dropped, keeping the named / better-tagged one.
 */
function dedupeBuildings(list: BuildingData[]): BuildingData[] {
  const bb = list.map((b) => {
    let a = Infinity, c = Infinity, d = -Infinity, e = -Infinity;
    for (const [x, z] of b.pts) {
      a = Math.min(a, x); c = Math.min(c, z); d = Math.max(d, x); e = Math.max(e, z);
    }
    return [a, c, d, e];
  });
  const score = (b: BuildingData) => (b.name ? 4 : 0) + (b.levels ? 2 : 0) + (b.source === 'ms' ? -1 : 0);
  const drop = new Set<number>();
  for (let i = 0; i < list.length; i += 1) {
    for (let j = i + 1; j < list.length; j += 1) {
      const A = bb[i], B = bb[j];
      if (A[2] < B[0] || B[2] < A[0] || A[3] < B[1] || B[3] < A[1]) continue;
      let inA = 0, inB = 0, both = 0;
      const step = 0.75;
      for (let x = Math.max(A[0], B[0]); x <= Math.min(A[2], B[2]); x += step) {
        for (let z = Math.max(A[1], B[1]); z <= Math.min(A[3], B[3]); z += step) {
          const p = pointInPoly(x, z, list[i].pts);
          const q = pointInPoly(x, z, list[j].pts);
          if (p) inA += 1;
          if (q) inB += 1;
          if (p && q) both += 1;
        }
      }
      if (!both) continue;
      // Share of the smaller footprint covered by the other.
      const areaI = Math.abs(polyArea(list[i].pts)) / (step * step);
      const areaJ = Math.abs(polyArea(list[j].pts)) / (step * step);
      if (both / Math.max(1, Math.min(areaI, areaJ)) < 0.6) continue;
      drop.add(score(list[i]) >= score(list[j]) ? j : i);
      void inA;
      void inB;
    }
  }
  return list.filter((_, i) => !drop.has(i));
}

/** Half-size of the playable square. */
export const WORLD_HALF = 420;
/** Where the campus road meets Lamachaur Marg: the main gate on the north side. */
export const GATE: Pt = [172.6, -257.3];

export function polyArea(p: Pt[]): number {
  let a = 0;
  for (let i = 0; i < p.length; i += 1) {
    const [x0, z0] = p[i];
    const [x1, z1] = p[(i + 1) % p.length];
    a += x0 * z1 - x1 * z0;
  }
  return a / 2;
}

export function centroid(p: Pt[]): Pt {
  let x = 0;
  let z = 0;
  for (const q of p) {
    x += q[0];
    z += q[1];
  }
  return [x / p.length, z / p.length];
}

export function pointInPoly(x: number, z: number, p: Pt[]): boolean {
  let inside = false;
  for (let i = 0, j = p.length - 1; i < p.length; j = i, i += 1) {
    const [xi, zi] = p[i];
    const [xj, zj] = p[j];
    if (zi > z !== zj > z && x < ((xj - xi) * (z - zi)) / (zj - zi) + xi) inside = !inside;
  }
  return inside;
}

/** Distance from (x, z) to segment a-b, with the closest point. */
export function segDist(x: number, z: number, a: Pt, b: Pt): { d: number; px: number; pz: number; t: number } {
  const dx = b[0] - a[0];
  const dz = b[1] - a[1];
  const l2 = dx * dx + dz * dz;
  const t = l2 > 0 ? Math.max(0, Math.min(1, ((x - a[0]) * dx + (z - a[1]) * dz) / l2)) : 0;
  const px = a[0] + dx * t;
  const pz = a[1] + dz * t;
  return { d: Math.hypot(x - px, z - pz), px, pz, t };
}

/** Distance from a point to a polygon's outline. */
export function polyEdgeDist(x: number, z: number, p: Pt[]): number {
  let best = Infinity;
  for (let i = 0; i < p.length; i += 1) best = Math.min(best, segDist(x, z, p[i], p[(i + 1) % p.length]).d);
  return best;
}

/** Minimum-area oriented rectangle (edge-aligned): centre, axis angle, half sizes. */
export function orientedRect(p: Pt[]): { cx: number; cz: number; angle: number; hl: number; hw: number } {
  let best = { cx: 0, cz: 0, angle: 0, hl: 0, hw: 0, area: Infinity };
  for (let i = 0; i < p.length; i += 1) {
    const a = p[i];
    const b = p[(i + 1) % p.length];
    const ang = Math.atan2(b[1] - a[1], b[0] - a[0]);
    const c = Math.cos(ang);
    const s = Math.sin(ang);
    let u0 = Infinity, u1 = -Infinity, v0 = Infinity, v1 = -Infinity;
    for (const q of p) {
      const u = q[0] * c + q[1] * s;
      const v = -q[0] * s + q[1] * c;
      u0 = Math.min(u0, u); u1 = Math.max(u1, u);
      v0 = Math.min(v0, v); v1 = Math.max(v1, v);
    }
    const area = (u1 - u0) * (v1 - v0);
    if (area < best.area) {
      const um = (u0 + u1) / 2;
      const vm = (v0 + v1) / 2;
      best = { cx: um * c - vm * s, cz: um * s + vm * c, angle: ang, hl: (u1 - u0) / 2, hw: (v1 - v0) / 2, area };
    }
  }
  // Long axis first.
  if (best.hw > best.hl) return { cx: best.cx, cz: best.cz, angle: best.angle + Math.PI / 2, hl: best.hw, hw: best.hl };
  return { cx: best.cx, cz: best.cz, angle: best.angle, hl: best.hl, hw: best.hw };
}

export function findBuilding(name: string): BuildingData | undefined {
  const n = name.toLowerCase();
  return DATA.buildings.find((b) => b.name?.toLowerCase() === n) ?? DATA.buildings.find((b) => b.name?.toLowerCase().includes(n));
}

export function findPoint(name: string): PointData | undefined {
  const n = name.toLowerCase();
  return DATA.points.find((p) => p.name?.toLowerCase() === n) ?? DATA.points.find((p) => p.name?.toLowerCase().includes(n));
}

export function findArea(name: string): AreaData | undefined {
  const n = name.toLowerCase();
  return DATA.areas.find((a) => a.name?.toLowerCase() === n) ?? DATA.areas.find((a) => a.name?.toLowerCase().includes(n));
}

/** The building whose footprint contains (or is nearest to) a point. */
export function buildingAt(x: number, z: number): BuildingData | undefined {
  let best: BuildingData | undefined;
  let bd = Infinity;
  for (const b of DATA.buildings) {
    if (pointInPoly(x, z, b.pts)) return b;
    const d = polyEdgeDist(x, z, b.pts);
    if (d < bd) {
      bd = d;
      best = b;
    }
  }
  return bd < 25 ? best : undefined;
}
